import json
def num(x): return x if isinstance(x,(int,float)) else 0.0
def load(p):
    r=[]
    for l in open(p):
        l=l.strip()
        if l: r.append(json.loads(l))
    return r
off=load("results/2026-10-12/m1-ngram/replay/off-greedy/requests.jsonl")
A  =load("results/2026-10-12/m1-ngram/replay/A-greedy/requests.jsonl")
offmap={ (r["phase"],r["id"]):r for r in off }
Amap  ={ (r["phase"],r["id"]):r for r in A }
print("shared (phase,id):", sum(1 for k in offmap if k in Amap), "of", len(offmap))
# compare predicted_n, finish_reason, cache_n for shared rows
diffs=[]
for k,(o,a) in sorted(offmap.items()):
    if k not in Amap: continue
    if o.get("predicted_n")!=a.get("predicted_n"):
        diffs.append((k, o.get("predicted_n"), a.get("predicted_n"), o.get("finish_reason"), a.get("finish_reason")))
print("predicted_n mismatches:", len(diffs))
for d in diffs[:15]:
    print("  ", d)
# length-finish detail in A
print("\nA length rows (predicted_n, cap?):")
for a in A:
    if a.get("finish_reason")=="length":
        # cap = max(recorded predicted_n, floor). need the floor; just show predicted_n
        print("  ", a["phase"], a.get("id"), "pred_n=", num(a.get("predicted_n")), "max_tok=", a.get("max_tokens"))
print("\noff length rows:")
for o in off:
    if o.get("finish_reason")=="length":
        print("  ", o["phase"], o.get("id"), "pred_n=", num(o.get("predicted_n")), "max_tok=", o.get("max_tokens"))
EOF

